mapper.select:
select a.notification_id, a.notification_type, a.target_id, a.created_at, a.receiver_id, a.sender_id, a.status,
b.profile_id as sender_profile_id, b.nickname as sender_nickname, b.stored_name as sender_profile_image
from notification_tbl a left join profile_tbl b on a.sender_id = b.user_id where a.notification_id = #{notificationId} and a.status = 'UNREAD' ;

select a.notification_id, a.notification_type, a.target_id, a.created_at, a.receiver_id, a.sender_id, a.status,
b.profile_id as sender_profile_id, b.nickname as sender_nickname, b.stored_name as sender_profile_image
from notification_tbl a left join profile_tbl b on a.sender_id = b.user_id where a.receiver_id = #{userId} and status = 'UNREAD' ORDER by a.created_at desc;

SELECT EXISTS(
    SELECT 1
    FROM notification_tbl
    WHERE sender_id = #{userId}
      AND receiver_id = #{receiverId}
      AND target_id = #{feedId}
      AND notification_type = 'LIKE'
)

SELECT EXISTS(
           SELECT 1
           FROM notification_tbl
           WHERE sender_id = #{userId}
             AND receiver_id = #{receiverId}
             AND notification_type = 'FRIEND_REQUEST'
             AND status = 'UNREAD');
